#!/usr/bin/env pwsh
$basedir=Split-Path $MyInvocation.MyCommand.Definition -Parent

$exe=""
$pathsep=":"
$env_node_path=$env:NODE_PATH
$new_node_path="C:\projects\coding-club-cms\node_modules\.pnpm\next@16.4.0_@types+node@20._542ef637b1a848145bcdf5aae4503fb8\node_modules\next\node_modules;C:\projects\coding-club-cms\node_modules\.pnpm\next@16.4.0_@types+node@20._542ef637b1a848145bcdf5aae4503fb8\node_modules;C:\projects\coding-club-cms\node_modules\.pnpm\node_modules"
if ($PSVersionTable.PSVersion -lt "6.0" -or $IsWindows) {
  # Fix case when both the Windows and Linux builds of Node
  # are installed in the same directory
  $exe=".exe"
  $pathsep=";"
} else {
  $new_node_path="/mnt/c/projects/coding-club-cms/node_modules/.pnpm/next@16.4.0_@types+node@20._542ef637b1a848145bcdf5aae4503fb8/node_modules/next/node_modules:/mnt/c/projects/coding-club-cms/node_modules/.pnpm/next@16.4.0_@types+node@20._542ef637b1a848145bcdf5aae4503fb8/node_modules:/mnt/c/projects/coding-club-cms/node_modules/.pnpm/node_modules"
}
if ([string]::IsNullOrEmpty($env_node_path)) {
  $env:NODE_PATH=$new_node_path
} else {
  $env:NODE_PATH="$new_node_path$pathsep$env_node_path"
}

$ret=0
if (Test-Path "$basedir/node$exe") {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "$basedir/node$exe"  "$basedir/../next/dist/bin/next" $args
  } else {
    & "$basedir/node$exe"  "$basedir/../next/dist/bin/next" $args
  }
  $ret=$LASTEXITCODE
} else {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "node$exe"  "$basedir/../next/dist/bin/next" $args
  } else {
    & "node$exe"  "$basedir/../next/dist/bin/next" $args
  }
  $ret=$LASTEXITCODE
}
$env:NODE_PATH=$env_node_path
exit $ret
